import torch as t

def solve(mods):
    class Chain(t.nn.Module):
        def __init__(self):
            super().__init__()
            i=0
            for mod in mods:
                self.add_module(str(i),mod)
                i+=1
        def forward(self,x):
            for name in self._modules:
                x=self._modules[name](x)
            return x
    return Chain()

