import torch as t

def solve(m,src,prefix):
    sd=m.state_dict()
    ps=src.state_dict()
    for k in sd:
        if k[:len(prefix)]==prefix:
            sd[k]=ps[k]
    m.load_state_dict(sd)
    return m

