import torch as t

def solve(m,src):
    sd=m.state_dict()
    ps=src.state_dict()
    differ=0
    for a,b in zip(list(sd),list(ps)):
        sd[a]=ps[b]
        if a!=b:
            differ+=1
    m.load_state_dict(sd)
    return (m,differ)

