answer_code:
import torch as t

def solve(m,x,target,lr,k):
    for step in [0]*k:
        loss=((m(x)-target)**2).mean()
        loss.backward()
        with t.no_grad():
            for p in m.parameters():
                p-=lr*p.grad
        m.zero_grad()
    return m

